"""Rate-based breaker: a short stall under traffic must NOT open it; a real outage must."""
import unittest
from unittest import mock

from decision_service import main     # if this import fails, copy the one used in tests/test_stepup.py


class BreakerRate(unittest.TestCase):
    def setUp(self):
        self.now = 1000.0                                    # fake clock, so the test runs instantly
        p = mock.patch.object(main.time, "monotonic", side_effect=lambda: self.now)
        p.start()
        self.addCleanup(p.stop)
        self.b = main.Breaker()

    def calls(self, n, failed, gap=0.03):                    # 0.03 s gap ~ 33 TPS, one pod's share
        for _ in range(n):
            (self.b.fail if failed else self.b.ok)()
            self.now += gap

    def test_short_stall_under_traffic_stays_closed(self):   # the bug seen in the replay
        self.calls(100, False)
        self.calls(8, True, gap=0)                           # one stall fails 8 overlapping requests
        self.assertTrue(self.b.allow())

    def test_outage_at_low_traffic_opens(self):              # what the 5B pause test does
        self.calls(5, True, gap=0.2)
        self.assertFalse(self.b.allow())

    def test_sustained_outage_under_traffic_opens(self):
        self.calls(100, False)
        self.calls(150, True)
        self.assertFalse(self.b.allow())

    def test_closes_again_after_open_period(self):
        self.calls(5, True, gap=0.2)
        self.now += main.BREAKER_OPEN_S
        self.assertTrue(self.b.allow())


if __name__ == "__main__":
    unittest.main()
